// Exterior following and fixed-platform views choose their own shell visibility.
export function cameraCuts109(mode,get){const automatic=['train','platform','passenger'].includes(mode);if(automatic)for(const id of['station-cutaway','environment-cutaway']){const control=get(id);control.checked=mode==='train';control.disabled=true;}const tools=get('follow107-tools');if(tools?.dataset)tools.dataset.automatic109=String(automatic);const status=get('follow109-status');if(status){status.hidden=!automatic;status.textContent=mode==='train'?'Corte automático · siguiendo al tren':mode==='passenger'?'Entorno completo · persona en andén':'Entorno completo · andén fijo';}}
